def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # A 3-colored 3x3 ring with a 2 center marks the stripe to extend from.
    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] == 2 and all(
                grid[rr][cc] == 3
                for rr, cc in ((r-1,c-1),(r-1,c),(r-1,c+1),
                               (r,c-1),(r,c+1),
                               (r+1,c-1),(r+1,c),(r+1,c+1))
            ):
                centers.append((r,c))
    # For vertical stripe layouts, extend rightward to the next 2 stripe,
    # painting the characteristic 1 motif across and reflected over it.
    for r, c in centers:
        if not all(grid[rr][cc] == 2 for rr in range(h) for cc in [c]):
            continue
        stripe = next((x for x in range(c + 1, w)
                       if all(grid[y][x] == 2 for y in range(h))), None)
        if stripe is None:
            continue
        d = stripe - c
        for offset in (2, 3, 4, d+1, d+2, d+3):
            x = c + offset
            if 0 <= x < w and grid[r][x] == 0:
                out[r][x] = 1
        for offset in (d-1, d+1):
            x = c + offset
            for y in (r-1, r+1):
                if 0 <= x < w and 0 <= y < h and grid[y][x] == 0:
                    out[y][x] = 1
    return out
