def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    rings = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] == 2 and all(grid[y][x] == 3 for y, x in (
                (r-1,c-1),(r-1,c),(r-1,c+1),
                (r,c-1),(r,c+1),
                (r+1,c-1),(r+1,c),(r+1,c+1))):
                rings.append((r, c))
    row_lines = [r for r in range(h) if sum(v == 2 for v in grid[r]) >= 0.7*w]
    col_lines = [c for c in range(w) if sum(grid[y][c] == 2 for y in range(h)) >= 0.7*h]
    for r, c in rings:
        if c in col_lines:
            others = [x for x in col_lines if x != c]
            if not others:
                continue
            right = [x for x in others if x > c]
            t = min(right) if right else max(others)
            # Color the row extending from the ring; preserve existing rails/ring.
            for x in range(w):
                if grid[r][x] == 0:
                    out[r][x] = 1
            # A three-wide crossing motif at the other rail; retain center 2.
            for y in range(r-1, r+2):
                for x in range(t-1, t+2):
                    if (0 <= y < h and 0 <= x < w and (y, x) != (r, t)
                            and grid[y][x] in (0, 2)):
                        out[y][x] = 1
        elif r in row_lines:
            others = [y for y in row_lines if y != r]
            if not others:
                continue
            below = [y for y in others if y > r]
            t = min(below) if below else max(others)
            for y in range(h):
                if grid[y][c] == 0:
                    out[y][c] = 1
            for y in range(t-1, t+2):
                for x in range(c-1, c+2):
                    if (0 <= y < h and 0 <= x < w and (y, x) != (t, c)
                            and grid[y][x] in (0, 2)):
                        out[y][x] = 1
    return out
